  1	import {
  2	  AutomaticProductionBlockedReceipt,
  3	  AutomaticProductionBlockedReceiptJson,
  4	  AutomaticProductionReceiptJson,
  5	  ProductionDeploymentsLive,
  6	  runAutomaticProduction,
  7	  VercelGitSha,
  8	} from "@bundjil/infrastructure/vercel";
  9	import { BunServices } from "@effect/platform-bun";
 10	import {
 11	  Cause,
 12	  Config,
 13	  Console,
 14	  Effect,
 15	  Exit,
 16	  Layer,
 17	  Match,
 18	  Option,
 19	  Schema,
 20	} from "effect";
 21	
 22	declare const process: {
 23	  exitCode: number | undefined;
 24	};
 25	
 26	const sourceSha = Config.schema(VercelGitSha, "BUNDJIL_PRODUCTION_SOURCE_SHA");
 27	const ProductionDeploymentsBunLive = ProductionDeploymentsLive.pipe(
 28	  Layer.provide(BunServices.layer)
 29	);
 30	const encodeBlocked = Schema.encodeEffect(
 31	  AutomaticProductionBlockedReceiptJson
 32	);
 33	
 34	const runProductionDeployment = Effect.gen(function* automaticProduction() {
 35	  const acceptedSourceSha = yield* sourceSha;
 36	  return yield* runAutomaticProduction(acceptedSourceSha).pipe(
 37	    Effect.provide(ProductionDeploymentsBunLive)
 38	  );
 39	});
 40	
 41	const main = Effect.gen(function* automaticProductionMain() {
 42	  const exit = yield* Effect.exit(
 43	    runProductionDeployment.pipe(
 44	      Effect.flatMap(Schema.encodeEffect(AutomaticProductionReceiptJson))
 45	    )
 46	  );
 47	  if (Exit.isSuccess(exit)) {
 48	    return yield* Console.log(exit.value);
 49	  }
 50	  const blockedReceipt = Option.match(Cause.findErrorOption(exit.cause), {
 51	    onNone: () =>
 52	      AutomaticProductionBlockedReceipt.make({
 53	        status: "blocked",
 54	        category: "unexpected",
 55	        operation: null,
 56	        project: null,
 57	        reason: null,
 58	        retry: null,
 59	      }),
 60	    onSome: (error) =>
 61	      Match.value(error).pipe(
 62	        Match.tag("ProductionDeploymentError", (failure) =>
 63	          AutomaticProductionBlockedReceipt.make({
 64	            status: "blocked",
 65	            category: "deployment",
 66	            operation: failure.operation,
 67	            project: failure.project,
 68	            reason: failure.reason,
 69	            retry: failure.retry,
 70	          })
 71	        ),
 72	        Match.tag("ConfigError", () =>
 73	          AutomaticProductionBlockedReceipt.make({
 74	            status: "blocked",
 75	            category: "configuration",
 76	            operation: null,
 77	            project: null,
 78	            reason: null,
 79	            retry: null,
 80	          })
 81	        ),
 82	        Match.orElse(() =>
 83	          AutomaticProductionBlockedReceipt.make({
 84	            status: "blocked",
 85	            category: "unexpected",
 86	            operation: null,
 87	            project: null,
 88	            reason: null,
 89	            retry: null,
 90	          })
 91	        )
 92	      ),
 93	  });
 94	  const blockedOutput = yield* encodeBlocked(blockedReceipt).pipe(Effect.orDie);
 95	  yield* Console.error(blockedOutput);
 96	  return yield* Effect.sync(() => {
 97	    process.exitCode = 1;
 98	  });
 99	});
100	
101	await Effect.runPromise(main);

