  1	import { Duration, Effect, Exit, Ref } from "effect";
  2	
  3	import { ProductionDeploymentError } from "./production.errors.js";
  4	import type {
  5	  AutomaticProductionReceipt,
  6	  ProductionDeployment,
  7	} from "./production.schemas.js";
  8	import { ProductionDeployments } from "./production.service.js";
  9	import type { VercelGitSha } from "./schemas.js";
 10	
 11	const targetError = (project: "agent" | "proxy") =>
 12	  new ProductionDeploymentError({
 13	    operation: "validate",
 14	    project,
 15	    reason: "targetMismatch",
 16	    retry: "never",
 17	  });
 18	
 19	const productionMutationTimeout = Duration.minutes(8);
 20	const productionRollbackTimeout = Duration.minutes(4);
 21	
 22	const rollbackTimeoutError = () =>
 23	  new ProductionDeploymentError({
 24	    operation: "rollback",
 25	    project: null,
 26	    reason: "timeout",
 27	    retry: "after-readback",
 28	  });
 29	
 30	const validateCandidate = (
 31	  candidate: ProductionDeployment,
 32	  expected: ProductionDeployment,
 33	  sourceSha: VercelGitSha
 34	) =>
 35	  candidate.project === expected.project &&
 36	  candidate.projectId === expected.projectId &&
 37	  candidate.deploymentId === expected.deploymentId &&
 38	  candidate.sourceSha === sourceSha
 39	    ? Effect.void
 40	    : Effect.fail(targetError(expected.project));
 41	
 42	export const runAutomaticProduction = Effect.fn("runAutomaticProduction")(
 43	  function* (sourceSha: VercelGitSha) {
 44	    const deployments = yield* ProductionDeployments;
 45	    const previousProxy = yield* deployments.current("proxy");
 46	    const previousAgent = yield* deployments.current("agent");
 47	    const previousAgentCallback = yield* deployments.currentAgentCallback;
 48	    const publicTargetsAreCurrent =
 49	      previousProxy.sourceSha === sourceSha &&
 50	      previousAgent.sourceSha === sourceSha;
 51	    const callbackIsCurrent =
 52	      previousAgentCallback.projectId === previousAgent.projectId &&
 53	      previousAgentCallback.deploymentId === previousAgent.deploymentId &&
 54	      previousAgentCallback.sourceSha === sourceSha;
 55	
 56	    if (publicTargetsAreCurrent && callbackIsCurrent) {
 57	      return {
 58	        status: "already-current",
 59	        sourceSha,
 60	        previousProxyDeploymentId: previousProxy.deploymentId,
 61	        previousAgentDeploymentId: previousAgent.deploymentId,
 62	        previousAgentCallbackDeploymentId: previousAgentCallback.deploymentId,
 63	        proxyDeploymentId: null,
 64	        agentDeploymentId: null,
 65	        stableProxyDeploymentId: previousProxy.deploymentId,
 66	        stableAgentDeploymentId: previousAgent.deploymentId,
 67	        stableAgentCallbackDeploymentId: previousAgentCallback.deploymentId,
 68	        rollbackReady: true,
 69	      } satisfies AutomaticProductionReceipt;
 70	    }
 71	
 72	    const candidateProxy = publicTargetsAreCurrent
 73	      ? previousProxy
 74	      : yield* deployments.stage({ project: "proxy", sourceSha });
 75	    const candidateAgent = publicTargetsAreCurrent
 76	      ? previousAgent
 77	      : yield* deployments.stage({ project: "agent", sourceSha });
 78	
 79	    if (!publicTargetsAreCurrent) {
 80	      yield* validateCandidate(
 81	        yield* deployments.inspect({
 82	          project: "proxy",
 83	          deploymentId: candidateProxy.deploymentId,
 84	        }),
 85	        candidateProxy,
 86	        sourceSha
 87	      );
 88	      yield* validateCandidate(
 89	        yield* deployments.inspect({
 90	          project: "agent",
 91	          deploymentId: candidateAgent.deploymentId,
 92	        }),
 93	        candidateAgent,
 94	        sourceSha
 95	      );
 96	    }
 97	
 98	    const currentMainSha = yield* deployments.readMainSha;
 99	    if (currentMainSha !== sourceSha) {
100	      return {
101	        status: "stale",
102	        sourceSha,
103	        previousProxyDeploymentId: previousProxy.deploymentId,
104	        previousAgentDeploymentId: previousAgent.deploymentId,
105	        previousAgentCallbackDeploymentId: previousAgentCallback.deploymentId,
106	        proxyDeploymentId: publicTargetsAreCurrent
107	          ? null
108	          : candidateProxy.deploymentId,
109	        agentDeploymentId: publicTargetsAreCurrent
110	          ? null
111	          : candidateAgent.deploymentId,
112	        stableProxyDeploymentId: previousProxy.deploymentId,
113	        stableAgentDeploymentId: previousAgent.deploymentId,
114	        stableAgentCallbackDeploymentId: previousAgentCallback.deploymentId,
115	        rollbackReady: true,
116	      } satisfies AutomaticProductionReceipt;
117	    }
118	
119	    const rollbackEligibility = yield* Ref.make<{
120	      readonly agent: boolean;
121	      readonly callback: boolean;
122	      readonly proxy: boolean;
123	    }>({ agent: false, callback: false, proxy: false });
124	
125	    const promotion = Effect.gen(function* () {
126	      if (!publicTargetsAreCurrent) {
127	        yield* Ref.update(rollbackEligibility, (current) => ({
128	          ...current,
129	          proxy: true,
130	        }));
131	        yield* deployments.promote(candidateProxy);
132	        yield* validateCandidate(
133	          yield* deployments.current("proxy"),
134	          candidateProxy,
135	          sourceSha
136	        );
137	        yield* Ref.update(rollbackEligibility, (current) => ({
138	          ...current,
139	          agent: true,
140	        }));
141	        yield* deployments.promote(candidateAgent);
142	        yield* validateCandidate(
143	          yield* deployments.current("agent"),
144	          candidateAgent,
145	          sourceSha
146	        );
147	      }
148	
149	      yield* Ref.update(rollbackEligibility, (current) => ({
150	        ...current,
151	        callback: true,
152	      }));
153	      yield* deployments.assignAgentCallback(candidateAgent);
154	      yield* validateCandidate(
155	        yield* deployments.currentAgentCallback,
156	        candidateAgent,
157	        sourceSha
158	      );
159	      yield* deployments.probeProxyHealth;
160	    });
161	
162	    yield* promotion.pipe(
163	      Effect.timeoutOrElse({
164	        duration: productionMutationTimeout,
165	        orElse: () =>
166	          Effect.fail(
167	            new ProductionDeploymentError({
168	              operation: "promote",
169	              project: null,
170	              reason: "timeout",
171	              retry: "after-readback",
172	            })
173	          ),
174	      }),
175	      Effect.onExit((promotionExit) => {
176	        if (Exit.isSuccess(promotionExit)) {
177	          return Effect.void;
178	        }
179	        return Effect.gen(function* rollbackProduction() {
180	          const eligible = yield* Ref.get(rollbackEligibility);
181	          const callbackRollbackExit = yield* Effect.exit(
182	            (eligible.callback
183	              ? Effect.gen(function* restoreCallback() {
184	                  yield* deployments.assignAgentCallback(previousAgentCallback);
185	                  yield* validateCandidate(
186	                    yield* deployments.currentAgentCallback,
187	                    previousAgentCallback,
188	                    previousAgentCallback.sourceSha
189	                  );
190	                })
191	              : Effect.void
192	            ).pipe(
193	              Effect.timeoutOrElse({
194	                duration: productionRollbackTimeout,
195	                orElse: () => Effect.fail(rollbackTimeoutError()),
196	              })
197	            )
198	          );
199	          const agentRollbackExit = yield* Effect.exit(
200	            (eligible.agent
201	              ? Effect.gen(function* restoreAgent() {
202	                  yield* deployments.rollback(previousAgent);
203	                  yield* validateCandidate(
204	                    yield* deployments.current("agent"),
205	                    previousAgent,
206	                    previousAgent.sourceSha
207	                  );
208	                })
209	              : Effect.void
210	            ).pipe(
211	              Effect.timeoutOrElse({
212	                duration: productionRollbackTimeout,
213	                orElse: () => Effect.fail(rollbackTimeoutError()),
214	              })
215	            )
216	          );
217	          const proxyRollbackExit = yield* Effect.exit(
218	            (eligible.proxy
219	              ? Effect.gen(function* restoreProxy() {
220	                  yield* deployments.rollback(previousProxy);
221	                  yield* validateCandidate(
222	                    yield* deployments.current("proxy"),
223	                    previousProxy,
224	                    previousProxy.sourceSha
225	                  );
226	                })
227	              : Effect.void
228	            ).pipe(
229	              Effect.timeoutOrElse({
230	                duration: productionRollbackTimeout,
231	                orElse: () => Effect.fail(rollbackTimeoutError()),
232	              })
233	            )
234	          );
235	          if (
236	            Exit.isFailure(callbackRollbackExit) ||
237	            Exit.isFailure(agentRollbackExit) ||
238	            Exit.isFailure(proxyRollbackExit)
239	          ) {
240	            return yield* new ProductionDeploymentError({
241	              operation: "rollback",
242	              project: null,
243	              reason: "rollbackFailed",
244	              retry: "after-readback",
245	            });
246	          }
247	          return yield* Effect.void;
248	        });
249	      })
250	    );
251	
252	    return {
253	      status: publicTargetsAreCurrent ? "callback-reconciled" : "promoted",
254	      sourceSha,
255	      previousProxyDeploymentId: previousProxy.deploymentId,
256	      previousAgentDeploymentId: previousAgent.deploymentId,
257	      previousAgentCallbackDeploymentId: previousAgentCallback.deploymentId,
258	      proxyDeploymentId: publicTargetsAreCurrent
259	        ? null
260	        : candidateProxy.deploymentId,
261	      agentDeploymentId: publicTargetsAreCurrent
262	        ? null
263	        : candidateAgent.deploymentId,
264	      stableProxyDeploymentId: candidateProxy.deploymentId,
265	      stableAgentDeploymentId: candidateAgent.deploymentId,
266	      stableAgentCallbackDeploymentId: candidateAgent.deploymentId,
267	      rollbackReady: true,
268	    } satisfies AutomaticProductionReceipt;
269	  }
270	);

