 1	import {
 2	  PhotonManagementCredentials,
 3	  PhotonManagementLive,
 4	} from "@bundjil/photon/management";
 5	import * as BunHttpClient from "@effect/platform-bun/BunHttpClient";
 6	import { Layer } from "effect";
 7	
 8	import type { AdoptionProviderScopes } from "./adoption-manifest.js";
 9	import { loadInfrastructurePhotonCredentials } from "./config.js";
10	import { layerPhotonReadOnlyProviders } from "./photon/providers.js";
11	import {
12	  VercelLive,
13	  VercelCredentialsLive,
14	  VercelProjectCredentialsLive,
15	} from "./vercel/live.layer.js";
16	import { layerVercelReadOnlyProviders } from "./vercel/providers.js";
17	import {
18	  VercelPreviewPhotonBindingValuesLive,
19	  VercelStableEnvironmentBindingsLive,
20	} from "./vercel/stable-environment-live.layer.js";
21	
22	const makeLiveStableAdoptionProviders = (
23	  scopes: AdoptionProviderScopes,
24	  vercelCredentials: typeof VercelCredentialsLive
25	) => {
26	  const photonCredentials = Layer.succeed(
27	    PhotonManagementCredentials,
28	    loadInfrastructurePhotonCredentials(scopes.photon.stage)
29	  );
30	  const transport = Layer.merge(BunHttpClient.layer, vercelCredentials);
31	  const vercelReads = VercelLive.pipe(Layer.provide(transport));
32	  const stableBindings = VercelStableEnvironmentBindingsLive.pipe(
33	    Layer.provide(transport)
34	  );
35	  const photonReads = PhotonManagementLive.pipe(
36	    Layer.provide(photonCredentials),
37	    Layer.provide(BunHttpClient.layer)
38	  );
39	  const providerServices = Layer.mergeAll(
40	    vercelReads,
41	    stableBindings,
42	    VercelPreviewPhotonBindingValuesLive,
43	    photonReads
44	  );
45	  const providers = Layer.merge(
46	    layerVercelReadOnlyProviders(scopes.vercel).pipe(
47	      Layer.provide(VercelPreviewPhotonBindingValuesLive),
48	      Layer.provide(stableBindings),
49	      Layer.provide(vercelReads)
50	    ),
51	    layerPhotonReadOnlyProviders(scopes.photon).pipe(Layer.provide(photonReads))
52	  );
53	  return Layer.merge(providers, providerServices);
54	};
55	
56	export const layerLiveStableAdoptionProviders = (
57	  scopes: AdoptionProviderScopes
58	) => makeLiveStableAdoptionProviders(scopes, VercelCredentialsLive);
59	
60	export const layerLiveStableAdoptionDriftProviders = (
61	  scopes: AdoptionProviderScopes
62	) => makeLiveStableAdoptionProviders(scopes, VercelProjectCredentialsLive);

